def encode(s):
    """Encode runs of the same character as character + run length.

    A run length of 1 is omitted.  The input is expected to contain only
    letters.
    """
    if not s:
        return ""

    result = []
    current = s[0]
    count = 1

    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            result.append(current)
            if count > 1:
                result.append(str(count))
            current = ch
            count = 1

    result.append(current)
    if count > 1:
        result.append(str(count))

    return "".join(result)


def decode(s):
    """Decode a string produced by :func:`encode`."""
    result = []
    i = 0
    n = len(s)

    while i < n:
        ch = s[i]
        i += 1

        start = i
        while i < n and s[i].isdigit():
            i += 1

        if start == i:
            count = 1
        else:
            count = int(s[start:i])

        result.append(ch * count)

    return "".join(result)


if __name__ == "__main__":
    assert encode("aaabcc") == "a3bc2"
    assert decode("a3bc2") == "aaabcc"
    assert decode(encode("aaaaaaaaaaaa")) == "aaaaaaaaaaaa"
